package vn.hust.restaurant.view;
import java.awt.*;import java.math.*;import java.time.*;import java.util.*;import javax.swing.*;import javax.swing.table.*;import vn.hust.restaurant.config.AppContext;import vn.hust.restaurant.model.*;import vn.hust.restaurant.repository.InventoryRepository;
public class InventoryPanel extends JPanel implements Refreshable{private final AppContext ctx;private final UserSession session;private final JTextField search=new JTextField(16);private final DefaultTableModel model=Ui.model("ID","Mã","Danh mục","Tên","ĐVT","Tồn","Định mức","Giá nhập","Cảnh báo");private final JTable table=new JTable(model);private java.util.List<Ingredient>data=java.util.List.of();public InventoryPanel(AppContext c,UserSession s){ctx=c;session=s;setLayout(new BorderLayout());JButton reload=new JButton("Tìm"),add=new JButton("Thêm/Sửa"),receive=new JButton("Nhập kho"),adjust=new JButton("Điều chỉnh"),recipe=new JButton("Công thức món"),supplier=new JButton("Nhà cung cấp");add(Ui.toolbar(new JLabel("Tìm:"),search,reload,add,receive,adjust,recipe,supplier),BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);reload.addActionListener(e->refresh());add.addActionListener(e->editIngredient());receive.addActionListener(e->receive());adjust.addActionListener(e->adjust());recipe.addActionListener(e->recipe());supplier.addActionListener(e->supplier());refresh();}
 public void refresh(){Ui.run(this,()->{data=ctx.inventory.list(search.getText());model.setRowCount(0);for(Ingredient x:data)model.addRow(new Object[]{x.id(),x.code(),x.categoryName(),x.name(),x.unit(),x.stock(),x.minimumStock(),x.lastCost(),x.lowStock()?"SẮP HẾT":""});});}
 private Ingredient selected(){int r=table.getSelectedRow();return r<0?null:data.get(r);}private void editIngredient(){Ui.run(this,()->{Ingredient x=selected();Map<Integer,String>cats=ctx.inventory.categories();JComboBox<String>cat=new JComboBox<>(cats.values().toArray(String[]::new));JTextField code=Ui.field(x==null?"NL"+(System.currentTimeMillis()%100000):x.code(),10),name=Ui.field(x==null?"":x.name(),18),unit=Ui.field(x==null?"kg":x.unit(),8),stock=Ui.field(x==null?"0":x.stock().toPlainString(),8),min=Ui.field(x==null?"0":x.minimumStock().toPlainString(),8),cost=Ui.field(x==null?"0":x.lastCost().toPlainString(),10);if(x!=null)cat.setSelectedIndex(Math.max(0,new ArrayList<>(cats.keySet()).indexOf(x.categoryId())));Object[]f={"Mã",code,"Danh mục",cat,"Tên",name,"ĐVT",unit,"Tồn",stock,"Định mức",min,"Giá nhập gần nhất",cost};if(JOptionPane.showConfirmDialog(this,f,"Nguyên liệu",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){int cid=new ArrayList<>(cats.keySet()).get(cat.getSelectedIndex());ctx.inventory.save(new Ingredient(x==null?0:x.id(),code.getText(),cid,String.valueOf(cat.getSelectedItem()),name.getText(),unit.getText(),Ui.dec(stock.getText()),Ui.dec(min.getText()),Ui.dec(cost.getText()),x==null?"HOAT_DONG":x.status()));refresh();}});}
 private void receive(){Ui.run(this,()->{Ingredient ing=selected();if(ing==null)throw new IllegalArgumentException("Chọn nguyên liệu");var sups=ctx.inventory.suppliers();if(sups.isEmpty())throw new IllegalArgumentException("Hãy tạo nhà cung cấp trước");JComboBox<InventoryRepository.Supplier>sup=new JComboBox<>(sups.toArray(InventoryRepository.Supplier[]::new));JTextField qty=Ui.field("1",8),cost=Ui.field(ing.lastCost().toPlainString(),10),expiry=Ui.field(LocalDate.now().plusMonths(3).format(Ui.D),12),note=Ui.field("",18);Object[]f={"Nguyên liệu",ing.name(),"Nhà cung cấp",sup,"Số lượng",qty,"Đơn giá",cost,"Hạn dùng",expiry,"Ghi chú",note};if(JOptionPane.showConfirmDialog(this,f,"Nhập kho",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){ctx.inventory.receive(session.employeeId(),((InventoryRepository.Supplier)sup.getSelectedItem()).id(),ing.id(),Ui.dec(qty.getText()),Ui.dec(cost.getText()),Ui.date(expiry.getText()),note.getText());refresh();}});}
 private void adjust(){Ingredient x=selected();if(x==null)return;JTextField delta=Ui.field("0",8),reason=Ui.field("Kiểm kê",18);if(JOptionPane.showConfirmDialog(this,new Object[]{"Nguyên liệu",x.name(),"Số lượng thay đổi (+/-)",delta,"Lý do",reason},"Điều chỉnh tồn",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)Ui.run(this,()->{ctx.inventory.adjust(session.employeeId(),x.id(),Ui.dec(delta.getText()),reason.getText());refresh();});}
 private void recipe(){Ui.run(this,()->{Ingredient ing=selected();if(ing==null)throw new IllegalArgumentException("Chọn nguyên liệu");var menu=ctx.menu.list("",false);JComboBox<vn.hust.restaurant.model.MenuItem>m=new JComboBox<>(menu.toArray(vn.hust.restaurant.model.MenuItem[]::new));JTextField amount=Ui.field("0.1",8);if(JOptionPane.showConfirmDialog(this,new Object[]{"Món",m,"Nguyên liệu",ing.name(),"Định lượng / 1 phần",amount},"Công thức",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)ctx.inventory.recipe(((vn.hust.restaurant.model.MenuItem)m.getSelectedItem()).id(),ing.id(),Ui.dec(amount.getText()));});}
 private void supplier(){Ui.run(this,()->{JTextField code=Ui.field("NCC"+(System.currentTimeMillis()%10000),10),name=Ui.field("",18),phone=Ui.field("",12),email=Ui.field("",18),addr=Ui.field("",20);if(JOptionPane.showConfirmDialog(this,new Object[]{"Mã",code,"Tên",name,"SĐT",phone,"Email",email,"Địa chỉ",addr},"Nhà cung cấp",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)ctx.inventory.supplier(new InventoryRepository.Supplier(0,code.getText(),name.getText(),phone.getText(),email.getText(),addr.getText(),"HOAT_DONG"));});}}
